def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 100:
                    aggressive_bids.append(bid)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 35.0))
        return float(min(budget, 8.0))

    competition = len(alive_opponents) + 1
    tight_supply = supply <= WATER_REQ * 1.6
    medium_supply = supply <= WATER_REQ * 2.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_prev = min(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        emergency = max(62.0, highest_prev + 3.0 if highest_prev > 0 else 62.0)
        return float(min(budget, emergency))

    if no_water_days >= 1 or hp <= 4:
        if tight_supply:
            urgent = max(48.0, min(72.0, highest_prev * 0.55 + 6.0 if highest_prev > 0 else 52.0))
            return float(min(budget, urgent))
        return float(min(budget, 34.0))

    if aggressive_bids:
        if tight_supply:
            bid = 26.0
        elif medium_supply:
            bid = 18.0
        else:
            bid = 10.0
    elif prev_bids:
        if highest_prev >= 60:
            bid = 24.0 if tight_supply else 15.0
        elif highest_prev >= 25:
            bid = min(32.0, highest_prev + 2.0)
            if not tight_supply:
                bid *= 0.7
        else:
            bid = max(9.0, low_prev + 2.0)
            if tight_supply:
                bid += 4.0
    else:
        bid = 16.0 if tight_supply else 10.0

    if competition >= 4 and tight_supply:
        bid += 4.0
    elif competition >= 3 and medium_supply:
        bid += 2.0

    if day >= 8 and hp >= 7 and no_water_days == 0:
        bid *= 0.9

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1
    fair_share = supply / num_agents

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], avg_prev * 1.1)

    if fair_share >= WATER_REQ:
        return min(my_status['budget'], avg_prev * 0.8)

    return min(my_status['budget'], avg_prev * 1.05)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Gather last bids from alive opponents (previous day trace)
    last_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                last_bids.append(prev['bid'])

    highest_last_bid = max(last_bids) if last_bids else 0.0

    # Base bid: slightly above highest opponent last bid if we need water
    if hp <= 2 or no_water_days >= 2:
        # desperate: bid up to salary
        bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        # moderate need: bid to beat opponents, but conserve
        bid = min(budget, max(highest_last_bid + 2, DAILY_SALARY * 0.5))
    else:
        # healthy: save money, bid low but still competitive
        bid = min(budget, max(highest_last_bid * 0.9, DAILY_SALARY * 0.4))

    # Adjust for supply: high supply needs lower bid
    if supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.6)
    elif supply <= 17:
        bid = max(bid, DAILY_SALARY * 0.7)

    # Ensure we don't exceed budget and stay non-negative
    return max(0, min(budget, bid))
